<?php
$zipData = base64_decode('');
file_put_contents('deploy_invitation.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_invitation.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_invitation.zip');
    
    // Clear views
    $viewsPath = __DIR__ . '/../storage/framework/views';
    $files = glob($viewsPath . '/*.php');
    if ($files) {
        foreach ($files as $file) {
            if (is_file($file)) unlink($file);
        }
    }
    
    // Clear routes cache if any
    if (file_exists(__DIR__ . '/../bootstrap/cache/routes-v7.php')) unlink(__DIR__ . '/../bootstrap/cache/routes-v7.php');
    
    echo '<h1>Invitation System Deployed!</h1>';
    echo '<p>PIN Lock has been replaced by the secure Email & QR Code Invitation System.</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>